          'culture',
          'fr',
          'article-slug',
          'custom-domain.dev'
        )
      ).toEqual('https://custom-domain.dev/hc/handbook/articles/article-slug');
    });

    it('handles https in custom domain correctly', () => {
      window.shopizConfig = {
        hostURL: 'https://app.shopiz.pro',
        helpCenterURL: 'https://help.shopiz.pro',
      };
      expect(
        buildPortalArticleURL(
          'handbook',
          'culture',
          'fr',
          'article-slug',
          'https://custom-domain.dev'
        )
      ).toEqual('https://custom-domain.dev/hc/handbook/articles/article-slug');
    });

    it('uses hostURL when helpCenterURL is not available', () => {
      window.shopizConfig = {
        hostURL: 'https://app.shopiz.pro',
        helpCenterURL: '',
      };
      expect(
        buildPortalArticleURL('handbook', 'culture', 'fr', 'article-slug')
      ).toEqual('https://app.shopiz.pro/hc/handbook/articles/article-slug');
    });
  });

  describe('buildLocaleMenuItems', () => {
    it('returns disabled actions for the default locale', () => {
      expect(
        buildLocaleMenuItems({
          isDefault: true,
          isDraft: false,
        })
      ).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ action: 'change-default', disabled: true }),
          expect.objectContaining({ action: 'move-to-draft', disabled: true }),
          expect.objectContaining({ action: 'delete', disabled: true }),
        ])
      );
    });

    it('returns publish and delete actions for draft locales', () => {
      expect(
        buildLocaleMenuItems({
          isDefault: false,
          isDraft: true,
        }).map(({ action }) => action)
      ).toEqual(['publish-locale', 'delete']);
    });

    it('returns default, draft, and delete actions for live locales', () => {
      expect(
        buildLocaleMenuItems({
          isDefault: false,
          isDraft: false,
        }).map(({ action }) => action)
      ).toEqual(['change-default', 'move-to-draft', 'delete']);
    });
  });
});

import { LocalStorage } from 'shared/helpers/localStorage';
import { LOCAL_STORAGE_KEYS } from 'dashboard/constants/localStorage';

export const setColorTheme = isOSOnDarkMode => {
  const kanbanCss = document.getElementById('kanban-css');
  const selectedColorScheme =
    LocalStorage.get(LOCAL_STORAGE_KEYS.COLOR_SCHEME) || 'light';
  if (
    (selectedColorScheme === 'auto' && isOSOnDarkMode) ||
    selectedColorScheme === 'dark'
  ) {
    document.body.classList.add('dark');
    document.documentElement.style.setProperty('color-scheme', 'dark');
    if(kanbanCss) {
      kanbanCss.href = "https://cdn.syncfusion.com/ej2/30.1.37/tailwind3-dark.css"
    }
  } else {
    document.body.classList.remove('dark');
    document.documentElement.style.setProperty('color-scheme', 'light');
    if(kanbanCss) {
      kanbanCss.href = "https://cdn.syncfusion.com/ej2/30.1.37/tailwind3.css"
    }
  }
};

